fileprivate struct Friction: System {
    var access: Access? { .writes(Velocity.self) }

    func run(in world: inout World) {
        world.update(Velocity.self) { velocity, _ in
            velocity.dx *= 0.5
        }
    }
}

// Sources/Systems/SystemMacro.swift:14
fileprivate struct Wind: Component { var speed: Double }

fileprivate struct Current: Component { var speed: Double }

@System
fileprivate struct Drift {
    func run(
        _ drifters: Update<Position>.Over<Velocity, AnyOf<Wind, Current>>,
        _ step: ResourceReader<TimeStep>
    ) {
        drifters { position, row in
            let (velocity, (wind, current)) = row.components
            let push = (wind?.speed ?? 0) + (current?.speed ?? 0)
            position.x += (velocity.dx + push) * step.value.seconds
        }
    }
}

