fileprivate struct SyncSprites: MainActorSystem {
    let sprites: [Sprite]
    var access: Access? { .reads(Position.self) }

    @MainActor func run(in world: inout World) {
        for sprite in sprites { sprite.step(in: &world) }
    }
}

