// Sources/Systems/Systems.docc/Systems.md:35
@System
fileprivate struct Gravity {
    func run(_ falling: Update<Velocity>.Where<Without<Frozen>>) {
        falling { velocity, _ in velocity.dy -= 10 }
    }
}

@System
fileprivate struct Movement {
    func run(_ movers: Update<Position>.Over<Velocity>.Where<Without<Frozen>>) {
        movers { position, row in
            position.x += row.components.dx
            position.y += row.components.dy
        }
    }
}

// Sources/Systems/Update.swift:32
@System
fileprivate struct Bounce {
    func run(_ bouncers: Update<Position>.And<Velocity>) {
        bouncers { position, velocity, _ in
            if position.y < 0 {
                position.y = -position.y
                velocity.dy = -velocity.dy
            }
        }
    }
}

